# Word count: lines, words, characters of the standard input, like `wc -lwm`.

type Wc = { lines: Int, words: Int, chars: Int, in_word: Bool }

# A counter never holds a negative tally.
fn inv_Wc(x: Wc) -> Bool = x.lines >= 0 && x.words >= 0 && x.chars >= 0

fn empty_wc() -> Wc = Wc { lines: 0, words: 0, chars: 0, in_word: false }

fn is_word_sep(c: Str) -> Bool =
  c == " " || c == "\t" || c == "\r" || c == "\n"

# Feed one character into the accumulator: a word starts at a non-separator
# character that follows a separator (or the start of the input).
fn wc_step(acc: Wc, c: Str) -> Wc =
  let sep = is_word_sep(c) in
  let nl = c == "\n" in
  Wc {
    lines: if nl then acc.lines + 1 else acc.lines,
    words: if sep then acc.words else (if acc.in_word then acc.words else acc.words + 1),
    chars: acc.chars + 1,
    in_word: !sep
  }

fn count(s: Str) -> Wc = fold(chars(s), empty_wc(), wc_step)

fn wc_line(w: Wc) -> Str =
  from_int(w.lines) ++ " " ++ from_int(w.words) ++ " " ++ from_int(w.chars)

fn main(args: List[Str]) -> Int !io =
  let input = read_all() in
  {
    print(wc_line(count(input)));
    0
  }

# --- tests: the benchmark examples and the edge cases of the definition ---

test example =
  count("hello world\nsecond line here\n") == Wc { lines: 2, words: 5, chars: 29, in_word: false }

test no_trailing_newline =
  count("one two\nthree") == Wc { lines: 1, words: 3, chars: 13, in_word: true }

test empty_input =
  count("") == empty_wc()

test only_newlines =
  count("\n\n\n") == Wc { lines: 3, words: 0, chars: 3, in_word: false }

test whitespace_only =
  count(" \t\r\n") == Wc { lines: 1, words: 0, chars: 4, in_word: false }

test runs_of_separators =
  count("  a   bb\t\tc\r\nd") == Wc { lines: 1, words: 4, chars: 14, in_word: true }

test crlf_lines =
  count("a b\r\nc d\r\n") == Wc { lines: 2, words: 4, chars: 10, in_word: false }

test unicode_code_points =
  count("héllo wörld") == Wc { lines: 0, words: 2, chars: 11, in_word: true }

test unicode_spaces_are_not_separators =
  count("a\u{00A0}b") == Wc { lines: 0, words: 1, chars: 3, in_word: true }

test tab_between_words =
  count("a\tb") == Wc { lines: 0, words: 2, chars: 3, in_word: true }

test wc_line_format =
  wc_line(Wc { lines: 2, words: 5, chars: 29, in_word: false }) == "2 5 29"

test inv_after_step =
  inv_Wc(wc_step(empty_wc(), "x")) && inv_Wc(wc_step(empty_wc(), " "))

# CSV column sum.
#
# Reads a CSV table from standard input, sums the integer values of one
# column (named by the single argument) and reports how many data rows were
# skipped.  Quoting only toggles "quoted mode": a double quote is never part
# of the value and commas inside quoted mode do not split fields.  Fields
# (header included) are stripped of leading and trailing spaces; an integer
# is an optional '+'/'-' followed by one or more decimal digits and nothing
# else.

# Sum and skipped-row counter for one table.
type Tally = { sum: Int, skipped: Int }

# Result of scanning a table: either the named column is absent, or the
# totals for it.
type CsvResult = NoColumn | Totals(Int, Int)

# Every output line plus the process exit code.
type CsvOutcome = { lines: List[Str], code: Int }

# Parser state for one CSV line: completed fields, the current
# field's characters and whether quoted mode is on.
type RowState = { done: List[Str], cur: List[Str], quoted: Bool }

# --- integers -------------------------------------------------------------

fn is_digit(c: Str) -> Bool =
  if len(c) != 1 then false
  else {
    let n = char_code(c) in
    n >= 48 && n <= 57
  }

fn all_digits(cs: List[Str]) -> Bool =
  fold(cs, true, fn(acc: Bool, c: Str) => acc && is_digit(c))

# Value of one decimal digit; 0 for anything else, so the folds stay total
# (the property tests feed arbitrary strings).
fn digit_value(c: Str) -> Int =
  if is_digit(c) then char_code(c) - 48 else 0

# Positive magnitude: accumulate positively so "-min_int" still parses.
fn digits_pos(cs: List[Str]) -> Int =
  fold(cs, 0, fn(acc: Int, c: Str) => acc * 10 + digit_value(c))

fn digits_neg(cs: List[Str]) -> Int =
  fold(cs, 0, fn(acc: Int, c: Str) => acc * 10 - digit_value(c))

# An integer is an optional '+' or '-' followed by one or more decimal digits
# and nothing else (no spaces: fields are already stripped).
fn parse_int(s: Str) -> Option[Int] =
  if len(s) == 0 then None
  else {
    let first = slice(s, 0, 1) in
    let signed = first == "+" || first == "-" in
    let body = if signed then slice(s, 1, len(s)) else s in
    if len(body) == 0 then None
    else {
      let cs = chars(body) in
      if !all_digits(cs) then None
      else Some(if first == "-" then digits_neg(cs) else digits_pos(cs))
    }
  }

# --- line and field text --------------------------------------------------

fn is_space_char(c: Str) -> Bool =
  c == " " || c == "\t" || c == "\r" || c == "\n"

# A line that is empty or holds only whitespace is ignored entirely.
fn is_blank(s: Str) -> Bool =
  fold(chars(s), true, fn(acc: Bool, c: Str) => acc && is_space_char(c))

# Drop one trailing carriage return so CRLF input behaves like LF input.
fn strip_cr(s: Str) -> Str =
  let n = len(s) in
  if n > 0 && slice(s, n - 1, n) == "\r" then slice(s, 0, n - 1) else s

fn ltrim_sp_at(s: Str, i: Int, n: Int) -> Str =
  let m = if n > len(s) then len(s) else n in
  if i < 0 then ltrim_sp_at(s, 0, m)
  else if i >= m then ""
  else if slice(s, i, i + 1) == " " then ltrim_sp_at(s, i + 1, m)
  else slice(s, i, m)

fn ltrim_sp(s: Str) -> Str = ltrim_sp_at(s, 0, len(s))

fn rtrim_sp_at(s: Str, i: Int) -> Str =
  let n = len(s) in
  if i >= n then rtrim_sp_at(s, n - 1)
  else if i < 0 then ""
  else if slice(s, i, i + 1) == " " then rtrim_sp_at(s, i - 1)
  else slice(s, 0, i + 1)

fn rtrim_sp(s: Str) -> Str = rtrim_sp_at(s, len(s) - 1)

# Strip leading and trailing spaces (not tabs: the spec says spaces).
fn strip_sp(s: Str) -> Str = rtrim_sp(ltrim_sp(s))

# --- CSV fields -----------------------------------------------------------

fn row_step(st: RowState, c: Str) -> RowState =
  if c == "\"" then RowState { done: st.done, cur: st.cur, quoted: !st.quoted }
  else if c == "," && !st.quoted then {
    RowState { done: push(st.done, join(st.cur, "")), cur: [], quoted: false }
  } else {
    RowState { done: st.done, cur: push(st.cur, c), quoted: st.quoted }
  }

# Split one line into fields and strip each field's surrounding spaces.
fn parse_row(line: Str) -> List[Str] =
  let st = fold(chars(line), RowState { done: [], cur: [], quoted: false }, row_step) in
  let all = push(st.done, join(st.cur, "")) in
  map(all, fn(f: Str) => strip_sp(f))

fn find_col_at(fields: List[Str], name: Str, i: Int) -> Option[Int] =
  if i >= len(fields) then None
  else match get(fields, i) {
    Some(f) => if f == name then Some(i) else find_col_at(fields, name, i + 1),
    None => None
  }

# Position of the header field whose stripped name is exactly `name`.
fn find_col(fields: List[Str], name: Str) -> Option[Int] =
  find_col_at(fields, name, 0)

# --- table scan -----------------------------------------------------------

fn add_row(acc: Tally, line: Str, col: Int) -> Tally =
  match get(parse_row(line), col) {
    None => Tally { sum: acc.sum, skipped: acc.skipped + 1 },
    Some(f) => match parse_int(f) {
      None => Tally { sum: acc.sum, skipped: acc.skipped + 1 },
      Some(v) => Tally { sum: acc.sum + v, skipped: acc.skipped }
    }
  }

# Non-blank lines of the input, carriage returns removed.
fn clean_lines(input: Str) -> List[Str] =
  filter(
    map(split(input, "\n"), fn(l: Str) => strip_cr(l)),
    fn(l: Str) => !is_blank(l)
  )

# The first non-blank line is the header; every later non-blank line is a
# data row.  A row without an integer in the named position is skipped.
fn csv_sum(name: Str, input: Str) -> CsvResult =
  let lines = clean_lines(input) in
  if len(lines) == 0 then NoColumn
  else match find_col(parse_row(list_at(lines, 0)), name) {
    None => NoColumn,
    Some(col) => {
      let t = fold(
        range(1, len(lines)),
        Tally { sum: 0, skipped: 0 },
        fn(acc: Tally, i: Int) => add_row(acc, list_at(lines, i), col)
      ) in
      Totals(t.sum, t.skipped)
    }
  }

# --- entry point ----------------------------------------------------------

fn csv_main(arg_count: Int, name: Str, input: Str) -> CsvOutcome =
  if arg_count != 1 then {
    CsvOutcome { lines: ["usage: csv_sum <column>"], code: 2 }
  } else match csv_sum(name, input) {
    NoColumn => CsvOutcome { lines: ["error: no column " ++ name], code: 1 },
    Totals(s, k) => CsvOutcome {
      lines: ["sum " ++ from_int(s), "skipped " ++ from_int(k)],
      code: 0
    }
  }

fn main(args: List[Str]) -> Int !io =
  let input = read_all() in
  let name = match get(args, 0) { Some(n) => n, None => "" } in
  let out = csv_main(len(args), name, input) in
  {
    print(join(out.lines, "\n"));
    out.code
  }

# --- tests ----------------------------------------------------------------

test example = csv_main(1, "qty", "item,qty,price\napple,3,10\npear,x,5\nfig,4,7\n") == CsvOutcome { lines: ["sum 7", "skipped 1"], code: 0 }

test missing_column = csv_main(1, "c", "a,b\n1,2\n") == CsvOutcome { lines: ["error: no column c"], code: 1 }

test quoted_commas = csv_main(1, "pop", "name,city,pop\n\"Doe, J\",\"Paris, FR\",100\nX,\"Y\",-20\n") == CsvOutcome { lines: ["sum 80", "skipped 0"], code: 0 }

test quoted_header = csv_main(1, "c", "\"a b\",\"c\"\n1,2\n3,4\n") == CsvOutcome { lines: ["sum 6", "skipped 0"], code: 0 }

test short_rows = csv_main(1, "c", "a,b,c\n1,2,3\n4\n5,6\n") == CsvOutcome { lines: ["sum 3", "skipped 2"], code: 0 }

test signs_and_spaces = csv_main(1, "v", "v\n+5\n -3 \n- 4\n7a\n\n  \n10\n") == CsvOutcome { lines: ["sum 12", "skipped 2"], code: 0 }

test crlf = csv_main(1, "v", "k,v\r\na,1\r\nb,2\r\n") == CsvOutcome { lines: ["sum 3", "skipped 0"], code: 0 }

test usage_no_args = csv_main(0, "", "a\n1\n") == CsvOutcome { lines: ["usage: csv_sum <column>"], code: 2 }

test usage_two_args = csv_main(2, "a", "a\n1\n") == CsvOutcome { lines: ["usage: csv_sum <column>"], code: 2 }

test empty_input = csv_main(1, "a", "") == CsvOutcome { lines: ["error: no column a"], code: 1 }

test blank_lines_ignored = csv_main(1, "x", "\n  \n x \n\t\n5\n\n") == CsvOutcome { lines: ["sum 5", "skipped 0"], code: 0 }

test negative_total = csv_main(1, "n", "n\n-5\n-1\n") == CsvOutcome { lines: ["sum -6", "skipped 0"], code: 0 }

test extra_fields_ok = csv_main(1, "b", "a,b\n1,2,3\n4,5\n") == CsvOutcome { lines: ["sum 7", "skipped 0"], code: 0 }

test first_header_wins = csv_main(1, "a", "a,a\n1,2\n") == CsvOutcome { lines: ["sum 1", "skipped 0"], code: 0 }

test parse_int_forms =
  parse_int("-20") == Some(-20)
  && parse_int("+5") == Some(5)
  && parse_int("007") == Some(7)
  && parse_int("0") == Some(0)
  && parse_int("-0") == Some(0)
  && parse_int("- 4") == None
  && parse_int(" 5") == None
  && parse_int("5 ") == None
  && parse_int("7a") == None
  && parse_int("") == None
  && parse_int("+") == None
  && parse_int("-") == None
  && parse_int("--1") == None

test parse_row_quotes =
  parse_row("\"a b\",c , \"d,e\"") == ["a b", "c", "d,e"]
  && parse_row("a\"b\",c") == ["ab", "c"]
  && parse_row("") == [""]
  && parse_row("a,,b") == ["a", "", "b"]

test strip_spaces =
  strip_sp("  x  ") == "x" && strip_sp("x") == "x" && strip_sp("   ") == ""

test find_column =
  find_col(["a", "b"], "b") == Some(1)
  && find_col(["a", "b"], "c") == None
  && find_col([], "a") == None
  && find_col(["a", "b"], "a") == Some(0)

test clean_lines_blank_filter =
  clean_lines("\n a \n\t\n\r\nb") == [" a ", "b"]

# Binary search over an ascending integer list.
# Input: line 1 holds ascending integers separated by single spaces (may be
# empty); every further line holds one integer query (maybe padded by spaces).
# Output: for each query the 0-based index of its first occurrence, else -1.

# First index i in [lo, hi) with xs[i] >= target (hi for none).
fn lower_bound(xs: List[Int], lo: Int, hi: Int, target: Int) -> Int =
  if lo >= hi then lo
  else
    let mid = lo + (hi - lo) / 2 in
    match get(xs, mid) {
      Some(v) => if v < target then lower_bound(xs, mid + 1, hi, target)
                 else lower_bound(xs, lo, mid, target),
      None => lo
    }

# Index of the first occurrence of target in the ascending list, or -1.
fn find_first(xs: List[Int], target: Int) -> Int =
  let i = lower_bound(xs, 0, len(xs), target) in
  match get(xs, i) {
    Some(v) => if v == target then i else -1,
    None => -1
  }

# Parse one input line of space separated integers into an ascending list.
fn parse_nums(line: Str) -> List[Int] =
  let toks = filter(split(trim(line), " "), fn(t: Str) => len(t) > 0) in
  let start: Accum[Int] = AccEnd in
  let built = fold(toks, start, fn(a: Accum[Int], t: Str) =>
    match to_int(t) { Some(n) => AccPush(a, n), None => a }) in
  acc_list(built)

# One query: its integer value, ignoring blank or malformed lines.
fn parse_query(line: Str) -> Option[Int] =
  to_int(trim(line))

fn answer_queries(nums: List[Int]) -> Unit !io =
  match read_line() {
    None => (),
    Some(line) =>
      match parse_query(line) {
        None => answer_queries(nums),
        Some(q) => { print(from_int(find_first(nums, q))); answer_queries(nums) }
      }
  }

fn main(args: List[Str]) -> Int !io =
  match read_line() {
    None => 0,
    Some(first) => { answer_queries(parse_nums(first)); 0 }
  }

# --- tests: the examples and edge cases ---

test find_example = find_first([1, 3, 3, 5, 8], 3) == 1
test find_example_absent = find_first([1, 3, 3, 5, 8], 4) == -1
test find_example_last = find_first([1, 3, 3, 5, 8], 8) == 4
test find_example_first = find_first([1, 3, 3, 5, 8], 1) == 0
test find_empty = find_first([], 5) == -1
test find_single = find_first([7], 7) == 0
test find_single_absent = find_first([7], 6) == -1
test find_negatives = find_first([-9, -4, -4, 0, 2], -4) == 1
test find_negatives_first = find_first([-9, -4, -4, 0, 2], -9) == 0
test find_duplicates = find_first([1, 1, 1, 3, 3, 7], 7) == 5
test parse_example = parse_nums("1 3 3 5 8") == [1, 3, 3, 5, 8]
test parse_empty = parse_nums("") == []
test parse_padded = parse_nums("  -9  -4 0 ") == [-9, -4, 0]
test parse_one = parse_nums("42") == [42]
test parse_query_padded = parse_query("  12  ") == Some(12)
test parse_query_blank = parse_query("   ") == None

# Bank account state machine.
#
# The whole behaviour is pure: run_text maps the input text to the list of
# output lines. main only reads stdin and prints those lines.

type State = { accounts: Map[Str, Int], out: List[Str] }

fn empty_state() -> State = State { accounts: map_new(), out: [] }

fn tok(xs: List[Str], i: Int) -> Str =
  match get(xs, i) { Some(x) => x, None => "" }

fn emit_msg(st: State, msg: Str) -> State =
  State { accounts: st.accounts, out: push(st.out, msg) }

fn balance_of(accounts: Map[Str, Int], name: Str) -> Int =
  match map_get(accounts, name) { Some(b) => b, None => 0 }

fn is_digit_char(c: Str) -> Bool = contains("0123456789", c)

fn all_digits(s: Str) -> Bool =
  fold(chars(s), true, fn(ok: Bool, c: Str) => ok && is_digit_char(c))

# An amount is 1 to 12 decimal digits (no sign) with a value greater than 0.
fn parse_amount(s: Str) -> Option[Int] =
  if len(s) == 0 then None
  else if len(s) > 12 then None
  else if !all_digits(s) then None
  else match to_int(s) {
    Some(n) => if n > 0 then Some(n) else None,
    None => None
  }

fn do_open(st: State, name: Str) -> State =
  if map_has(st.accounts, name) then
    emit_msg(st, "error: account " ++ name ++ " exists")
  else State { accounts: map_put(st.accounts, name, 0), out: st.out }

fn do_balance(st: State, name: Str) -> State =
  match map_get(st.accounts, name) {
    Some(b) => emit_msg(st, name ++ " " ++ from_int(b)),
    None => emit_msg(st, "error: no account " ++ name)
  }

fn add_balance(st: State, name: Str, delta: Int) -> State =
  State {
    accounts: map_put(st.accounts, name, balance_of(st.accounts, name) + delta),
    out: st.out
  }

fn do_deposit(st: State, name: Str, raw: Str) -> State =
  if !map_has(st.accounts, name) then
    emit_msg(st, "error: no account " ++ name)
  else match parse_amount(raw) {
    None => emit_msg(st, "error: invalid amount"),
    Some(v) => add_balance(st, name, v)
  }

fn do_withdraw(st: State, name: Str, raw: Str) -> State =
  if !map_has(st.accounts, name) then
    emit_msg(st, "error: no account " ++ name)
  else match parse_amount(raw) {
    None => emit_msg(st, "error: invalid amount"),
    Some(v) =>
      if balance_of(st.accounts, name) < v then
        emit_msg(st, "error: insufficient funds")
      else add_balance(st, name, -v)
  }

fn do_transfer(st: State, from: Str, to: Str, raw: Str) -> State =
  if !map_has(st.accounts, from) then
    emit_msg(st, "error: no account " ++ from)
  else if !map_has(st.accounts, to) then
    emit_msg(st, "error: no account " ++ to)
  else match parse_amount(raw) {
    None => emit_msg(st, "error: invalid amount"),
    Some(v) =>
      if balance_of(st.accounts, from) < v then
        emit_msg(st, "error: insufficient funds")
      else if from == to then st
      else {
        let after = map_put(
          st.accounts,
          from,
          balance_of(st.accounts, from) - v
        ) in
        State {
          accounts: map_put(after, to, balance_of(st.accounts, to) + v),
          out: st.out
        }
      }
  }

fn step(st: State, line: Str) -> State = {
  let toks = split(line, " ") in
  let n = len(toks) in
  let cmd = tok(toks, 0) in
  if n == 2 then {
    let a = tok(toks, 1) in
    if cmd == "open" then do_open(st, a)
    else if cmd == "balance" then do_balance(st, a)
    else emit_msg(st, "error: invalid command")
  } else if n == 3 then {
    let a = tok(toks, 1) in
    let b = tok(toks, 2) in
    if cmd == "deposit" then do_deposit(st, a, b)
    else if cmd == "withdraw" then do_withdraw(st, a, b)
    else emit_msg(st, "error: invalid command")
  } else if n == 4 then {
    let a = tok(toks, 1) in
    let b = tok(toks, 2) in
    let c = tok(toks, 3) in
    if cmd == "transfer" then do_transfer(st, a, b, c)
    else emit_msg(st, "error: invalid command")
  } else emit_msg(st, "error: invalid command")
}

fn has_suffix(s: Str, suf: Str) -> Bool =
  if len(suf) > len(s) then false
  else slice(s, len(s) - len(suf), len(s)) == suf

fn strip_cr(s: Str) -> Str =
  if has_suffix(s, "\r") then slice(s, 0, len(s) - 1) else s

fn split_lines(text: Str) -> List[Str] =
  if text == "" then []
  else {
    let body =
      if has_suffix(text, "\n") then slice(text, 0, len(text) - 1) else text in
    map(split(body, "\n"), strip_cr)
  }

fn account_lines(accounts: Map[Str, Int]) -> List[Str] =
  map(
    sort_str(map_keys(accounts)),
    fn(k) => k ++ " " ++ from_int(balance_of(accounts, k))
  )

fn render(st: State) -> List[Str] =
  concat(st.out, concat(["---"], account_lines(st.accounts)))

fn run_lines(lines: List[Str]) -> List[Str] =
  render(fold(lines, empty_state(), step))

fn run_text(text: Str) -> List[Str] = run_lines(split_lines(text))

# ---------------------------------------------------------------- tests

test example =
  run_text(
    "open alice\ndeposit alice 100\nwithdraw alice 30\nopen bob\ntransfer alice bob 50\nbalance alice\nwithdraw bob 80\n"
  ) == ["alice 20", "error: insufficient funds", "---", "alice 20", "bob 50"]

test errors =
  run_text(
    "deposit x 5\nopen x\nopen x\ndeposit x 0\ndeposit x -1\ndeposit x 1.5\nwithdraw x 1\ntransfer x y 1\ntransfer y x 1\nfly x\n\nbalance\n"
  ) == [
    "error: no account x",
    "error: account x exists",
    "error: invalid amount",
    "error: invalid amount",
    "error: invalid amount",
    "error: insufficient funds",
    "error: no account y",
    "error: no account y",
    "error: invalid command",
    "error: invalid command",
    "error: invalid command",
    "---",
    "x 0"
  ]

test same_account_transfer =
  run_text(
    "open a\ndeposit a 100\ntransfer a a 40\nbalance a\ntransfer a a 200\nbalance a\n"
  ) == ["a 100", "error: insufficient funds", "a 100", "---", "a 100"]

test account_order =
  run_text(
    "open alice\nopen Bob\nopen Zed\ndeposit Bob 5\ndeposit Zed 7\ndeposit alice 3\n"
  ) == ["---", "Bob 5", "Zed 7", "alice 3"]

test case_sensitive =
  run_text("open A\nopen a\ndeposit A 5\nbalance a\nbalance A\n") ==
    ["a 0", "A 5", "---", "A 5", "a 0"]

test invalid_commands =
  run_text(
    "open\nopen a b\nfly\ndeposit a\nbalance a b\n  \ntransfer a b\ntransfer a b c d\n"
  ) == [
    "error: invalid command",
    "error: invalid command",
    "error: invalid command",
